class OrderProcessor {
    private Connection dbConnection;
    private Properties smtpConfig;

    void processOrder(String customerEmail, double amount, int quantity) {

        // concern 1: validation

        if (amount <= 0 || quantity <= 0)
            throw new IllegalArgumentException("Invalid order");
        if (!customerEmail.contains("@"))
            throw new IllegalArgumentException("Invalid email");

        // concern 2: business logic

        double discount = quantity > 10 ? 0.1 : 0.0;
        double total = amount * quantity * (1 - discount);
        double tax = total * 0.08;
        double finalAmount = total + tax;

        // concern 3: persistence

        try {
            PreparedStatement stmt = dbConnection.prepareStatement(
                "INSERT INTO orders (email, amount, qty, total) VALUES (?,?,?,?)");
            stmt.setString(1, customerEmail);
            stmt.setDouble(2, amount);
            stmt.setInt(3, quantity);
            stmt.setDouble(4, finalAmount);
            stmt.executeUpdate();
        } catch (SQLException e) { throw new RuntimeException(e); }

        // concern 4: notification

        try {
            Session session = Session.getInstance(smtpConfig);
            Message msg = new MimeMessage(session);
            msg.setRecipients(Message.RecipientType.TO, customerEmail);
            msg.setSubject("Order confirmed");
            msg.setText("Your total: $" + finalAmount);
            Transport.send(msg);
        } catch (MessagingException e) { throw new RuntimeException(e); }
    }
}

