import functools


# Logging as a cross-cutting concern, added externally via a decorator,
# the same spirit as Spring AOP's @Around advice
def log_execution(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}")
        try:
            return func(*args, **kwargs)
        finally:
            print(f"Finished {func.__name__}")
    return wrapper


class OrderService:
    @log_execution
    def process_order(self, email, amount):
        print(f"Processing order for {email}, amount {amount} dollars")


# OrderService's own logic never imports a logging module, the concern is external

if __name__ == "__main__":
    OrderService().process_order("customer@example.com", 199.99)

