import java.lang.reflect.*;

interface OrderService {
    void processOrder(String email, double amount);
}

class OrderServiceImpl implements OrderService {
    public void processOrder(String email, double amount) {
        System.out.println("Processing order for " + email + ", amount $" + amount);
    }
}

// Logging as a cross-cutting concern, added externally via a dynamic proxy,
// the same spirit as Spring AOP's @Around advice, without needing a Spring container
class LoggingProxy implements InvocationHandler {
    private final Object target;
    LoggingProxy(Object target) { this.target = target; }

    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        System.out.println("Calling " + method.getName());
        try {
            return method.invoke(target, args);
        } finally {
            System.out.println("Finished " + method.getName());
        }
    }

    static OrderService wrap(OrderService target) {
        return (OrderService) Proxy.newProxyInstance(
            OrderService.class.getClassLoader(),
            new Class<?>[]{OrderService.class},
            new LoggingProxy(target)
        );
    }
}
// OrderServiceImpl itself never imports a logging class, the concern is external

public class Main {
    public static void main(String[] args) {
        OrderService service = LoggingProxy.wrap(new OrderServiceImpl());
        service.processOrder("customer@example.com", 199.99);
    }
}

