#include <bits/stdc++.h>
using namespace std;

class OrderService {
public:
    void processOrder(const string& email, double amount) {
        cout << "Processing order for " << email << ", amount $" << amount << endl;
    }
};

// Logging as a cross-cutting concern, added externally via a wrapping function,
// the same spirit as Spring AOP's @Around advice (C++ has no reflection-based AOP,
// so a simple wrapper function is the idiomatic equivalent here)
template <typename Func>
void logExecution(const string& name, Func action) {
    cout << "Calling " << name << endl;
    action();
    cout << "Finished " << name << endl;
}
// OrderService itself never includes any logging code, the concern is external

int main() {
    OrderService service;
    logExecution("processOrder", [&]() {
        service.processOrder("customer@example.com", 199.99);
    });
    return 0;
}
